{
  "name": "cheerio",
  "version": "1.2.0",
  "description": "The fast, flexible & elegant library for parsing and manipulating HTML and XML.",
  "keywords": [
    "htmlparser",
    "jquery",
    "selector",
    "scraper",
    "parser",
    "dom",
    "xml",
    "html"
  ],
  "homepage": "https://cheerio.js.org/",
  "bugs": {
    "url": "https://github.com/cheeriojs/cheerio/issues"
  },
  "repository": {
    "type": "git",
    "url": "git://github.com/cheeriojs/cheerio.git"
  },
  "funding": "https://github.com/cheeriojs/cheerio?sponsor=1",
  "license": "MIT",
  "author": "Matt Mueller <mattmuelle@gmail.com>",
  "sideEffects": false,
  "maintainers": [
    "Felix Boehm <me@feedic.com>"
  ],
  "type": "module",
  "exports": {
    ".": {
      "import": {
        "browser": {
          "types": "./dist/esm/browser/index.d.ts",
          "default": "./dist/esm/browser/index.js"
        },
        "types": "./dist/esm/index.d.ts",
        "default": "./dist/esm/index.js"
      },
      "require": {
        "types": "./dist/commonjs/index.d.ts",
        "default": "./dist/commonjs/index.js"
      }
    },
    "./package.json": "./package.json",
    "./slim": {
      "import": {
        "browser": {
          "types": "./dist/esm/browser/slim.d.ts",
          "default": "./dist/esm/browser/slim.js"
        },
        "types": "./dist/esm/slim.d.ts",
        "default": "./dist/esm/slim.js"
      },
      "require": {
        "types": "./dist/commonjs/slim.d.ts",
        "default": "./dist/commonjs/slim.js"
      }
    },
    "./utils": {
      "import": {
        "browser": {
          "types": "./dist/esm/browser/utils.d.ts",
          "default": "./dist/esm/browser/utils.js"
        },
        "types": "./dist/esm/utils.d.ts",
        "default": "./dist/esm/utils.js"
      },
      "require": {
        "types": "./dist/commonjs/utils.d.ts",
        "default": "./dist/commonjs/utils.js"
      }
    }
  },
  "main": "./dist/commonjs/index.js",
  "module": "./dist/esm/index.js",
  "browser": "./dist/esm/browser/index.js",
  "types": "./dist/commonjs/index.d.ts",
  "files": [
    "dist",
    "src",
    "!**/*.spec.{t,j}s",
    "!**/__tests__/*",
    "!**/__fixtures__/*"
  ],
  "scripts": {
    "benchmark": "node --import=tsx benchmark/benchmark.ts",
    "build": "tshy",
    "format": "npm run format:es && npm run format:biome",
    "format:biome": "biome check --write .",
    "format:es": "npm run lint:es -- --fix",
    "lint": "npm run lint:es && npm run lint:ts && npm run lint:biome",
    "lint:biome": "biome check .",
    "lint:es": "eslint .",
    "lint:ts": "tsc --noEmit",
    "prepare": "husky",
    "prepublishOnly": "npm run build",
    "test": "npm run lint && npm run test:vi",
    "test:vi": "vitest run",
    "update-sponsors": "tsx scripts/fetch-sponsors.mts"
  },
  "lint-staged": {
    "*.js": [
      "biome check --write",
      "eslint --fix"
    ],
    "*.{json,ts}": [
      "biome check --write"
    ]
  },
  "dependencies": {
    "cheerio-select": "^2.1.0",
    "dom-serializer": "^3.1.1",
    "domhandler": "^6.0.1",
    "domutils": "^4.0.2",
    "encoding-sniffer": "^1.0.2",
    "htmlparser2": "^12.0.0",
    "parse5": "^8.0.1",
    "parse5-htmlparser2-tree-adapter": "^8.0.1",
    "parse5-parser-stream": "^8.0.0",
    "undici": "^8.11.2",
    "whatwg-mimetype": "^5.0.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.5.15",
    "@eslint/compat": "^2.1.1",
    "@feedic/eslint-config": "^0.5.0",
    "@imgix/js-core": "^3.8.0",
    "@octokit/graphql": "^9.0.5",
    "@types/jsdom": "^30.0.0",
    "@types/node": "^26.6.4",
    "@types/whatwg-mimetype": "^5.0.0",
    "@vitest/coverage-v8": "^5.0.3",
    "@vitest/eslint-plugin": "^1.6.27",
    "eslint": "^10.12.0",
    "eslint-config-biome": "^2.1.3",
    "globals": "^17.13.0",
    "husky": "^9.1.7",
    "jquery": "^4.0.0",
    "jsdom": "^30.1.2",
    "lint-staged": "^17.6.0",
    "tinybench": "^6.2.1",
    "tshy": "^4.1.3",
    "tsx": "^4.23.15",
    "typescript": "^6.0.3",
    "typescript-eslint": "^8.71.1",
    "vitest": "^5.0.3"
  },
  "engines": {
    "node": ">=22.19.0"
  },
  "tshy": {
    "esmDialects": [
      "browser"
    ],
    "exports": {
      ".": "./src/index.ts",
      "./slim": "./src/slim.ts",
      "./utils": "./src/utils.ts",
      "./package.json": "./package.json"
    },
    "exclude": [
      "**/*.spec.ts",
      "**/__fixtures__/*",
      "**/__tests__/*"
    ]
  }
}
